import assert from 'node:assert/strict';
import { test } from 'node:test';
import { slugify } from '../src/slug.js';

test('slugify lowercases and joins runs with one hyphen (A1)', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
  assert.equal(slugify('a -- b__c'), 'a-b-c');
});

test('slugify never starts or ends with a hyphen (A2)', () => {
  assert.equal(slugify('  Hello, World!  '), 'hello-world', 'SLUG-TRIM: no leading or trailing hyphen');
});

