import { slugify } from './slug.js';

/** The page identifier of `title` and `n` (.roadmap/contracts/one.md, pageId). */
export function pageId(title, n) {
  if (!Number.isInteger(n) || n < 1) throw new RangeError(`n must be a positive integer, got ${n}`);
  return `${slugify(title)}-${n}`;
}

