import assert from 'node:assert/strict';
import { test } from 'node:test';
import { pageId } from '../src/page-id.js';

test('pageId joins the slug and n (B1)', () => {
  assert.equal(pageId('Hello World', 2), 'hello-world-2');
});

test('pageId refuses a bad n (B3)', () => {
  assert.throws(() => pageId('x', 0), RangeError);
  assert.throws(() => pageId('x', 1.5), RangeError);
});

test('an empty slug becomes page (B2)', () => {
  assert.equal(pageId('!!!', 3), 'page-3');
});
